'use strict';

const VERSION = 'gravicentra-payment-inference-engine-v1-b3005';

const text = (value, max = 500) => String(value == null ? '' : value).replace(/\u0000/g, '').trim().slice(0, max);
const norm = value => text(value, 180).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
const number = value => {
  if (value == null || value === '') return null;
  const n = Number(String(value).replace(/[^0-9.-]/g, ''));
  return Number.isFinite(n) ? n : null;
};
function installment(value) {
  const raw = text(value, 120).toUpperCase().replace(/^'/, '');
  const pair = raw.match(/(\d+)\s*(?:DE|\/)\s*(\d+)/);
  if (pair) return { index: Number(pair[1]), total: Number(pair[2]) };
  const single = raw.match(/(?:^|\D)(\d+)(?:\D|$)/);
  return { index: single ? Number(single[1]) : null, total: null };
}
function canonicalReceiptInstallment(row) {
  row = row || {};
  const indices = [], totals = [];
  let conflict = false;
  const present = value => value != null && value !== '';
  const quota = value => {
    if (!['string','number'].includes(typeof value)) return null;
    const match = /^'?(\d{1,3})(?:\s*(?:\/|de)\s*(\d{1,3}))?$/i.exec(String(value).trim());
    if (!match) return null;
    const index = Number(match[1]), total = match[2] == null ? null : Number(match[2]);
    return index > 0 && index <= 100 && (total == null || total >= index && total <= 100) ? {index,total} : null;
  };
  const accept = value => {
    const parsed = quota(value);
    if (!parsed) { conflict = true; return; }
    indices.push(parsed.index);
    if (parsed.total != null) totals.push(parsed.total);
  };
  for (const value of [row.secuencia,row.cuota,row.numeroCuota]) if (present(value)) accept(value);
  // Approved legacy receipts store their explicit quota in serie. A series
  // which is only an external document identifier is not a quota. An apparent
  // N/total label must be valid and agree with every canonical quota alias.
  if (present(row.serie)) {
    if (quota(row.serie)) accept(row.serie);
    else if (/^'?\d+\s*(?:\/|de)/i.test(String(row.serie).trim())) conflict = true;
  }
  // A requirement such as37260363 identifies an insurer document, never an
  // installment. Only an explicit N/total label in the old field is usable.
  if (present(row.numeroReciboFuente) && /^'?\d+\s*(?:\/|de)/i.test(String(row.numeroReciboFuente).trim()))
    accept(row.numeroReciboFuente);
  for (const value of [row.totalInstallments,row.totalCuotas]) if (present(value)) {
    if (!/^[0-9]{1,3}$/.test(String(value)) || Number(value) < 1 || Number(value) > 100) conflict = true;
    else totals.push(Number(value));
  }
  if (new Set(indices).size > 1 || new Set(totals).size > 1 ||
      indices.length && totals.length && indices[0] > totals[0]) conflict = true;
  return {index:conflict || !indices.length ? null : indices[0],total:conflict || !totals.length ? null : totals[0],conflict};
}
function receiptSequence(row) { return canonicalReceiptInstallment(row).index; }
function receiptDenominator(row) { return canonicalReceiptInstallment(row).total; }
function dueDate(row) {
  return text(row && (row.vence || row.fechaLimite || row.fechaVencimiento), 32);
}
function activeReceipt(row) {
  const state = norm(row && (row.estadoOperativo || row.estado || row.status));
  return !!row && !['anulado','anulada','cancelado','cancelada','superseded','reemplazado','reemplazada'].includes(state);
}
function alreadyPaid(row) {
  const state = norm(row && (row.paymentState || row.estadoOperativo || row.estado));
  return ['paid_direct','paid_inferred','paid_reported','pagado','pago_inferido','pago_reportado_aplicado','pago_reportado_asesor_aplicado'].includes(state);
}
function contradiction(row) {
  const state = norm(row && (row.paymentState || row.estadoOperativo || row.estado));
  if (['reversed','revertido','reversado','conflict_review_required','conflicto','hold'].includes(state)) return true;
  if (row && (row.pagoParcial === true || row.partialPayment === true || row.refinanciado === true || row.restructured === true)) return true;
  return false;
}
function evidenceKind(value) {
  const key = norm(value).toUpperCase();
  const map = {
    INVOICE_INSTALLMENT_N: 'INVOICE_INSTALLMENT_N',
    INSURER_INVOICE: 'INVOICE_INSTALLMENT_N',
    FACTURA_ASEGURADORA: 'INVOICE_INSTALLMENT_N',
    INSURER_STATEMENT_PENDING_FROM_N: 'INSURER_STATEMENT_PENDING_FROM_N',
    INSURER_STATEMENT: 'INSURER_STATEMENT_PENDING_FROM_N',
    ESTADO_CUENTA_ASEGURADORA: 'INSURER_STATEMENT_PENDING_FROM_N',
    COMMISSION_STATEMENT_INSTALLMENT_N: 'COMMISSION_STATEMENT_INSTALLMENT_N',
    COMMISSION_STATEMENT: 'COMMISSION_STATEMENT_INSTALLMENT_N',
    PLANILLA_COMISIONES: 'COMMISSION_STATEMENT_INSTALLMENT_N',
    BANK_STATEMENT_MATCH: 'BANK_STATEMENT_MATCH',
    BANK_STATEMENT: 'BANK_STATEMENT_MATCH'
  };
  return map[key] || '';
}
function normalizedTokens(policy) {
  policy = policy || {};
  return [policy.aseguradoraNombre, policy.insurerName, policy.aseguradora, policy.aseguradoraId, policy.insurerId]
    .map(norm).filter(Boolean);
}
function ruleForPolicy(config, policy) {
  const tokens = normalizedTokens(policy);
  const rules = Array.isArray(config && config.insurerPaymentPlans) ? config.insurerPaymentPlans : [];
  const matches = rules.filter(rule => {
    const ids = [rule.insurerId, rule.canonicalKey, rule.insurer, rule.name].concat(rule.aliases || []).map(norm).filter(Boolean);
    return ids.some(id => tokens.some(token => token === id || token.includes(id) || id.includes(token)));
  });
  return matches.length === 1 ? matches[0] : null;
}
function review(code, detail) {
  return Object.assign({
    ok: true,
    status: 'REVIEW_REQUIRED',
    autoCommit: false,
    confidence: 'LOW',
    humanReviewRequired: true,
    writes: 0,
    reason: code
  }, detail || {});
}
function explicitTotal(evidence, anchorReceipt) {
  const direct = number(evidence && (evidence.totalInstallments || evidence.installmentTotal || evidence.totalCuotas));
  if (direct != null && direct > 0) return Math.floor(direct);
  const fromEvidence = installment(evidence && (evidence.installment || evidence.cuota || evidence.anchorInstallmentLabel));
  if (fromEvidence.total) return fromEvidence.total;
  return receiptDenominator(anchorReceipt);
}
function anchorIndex(evidence) {
  const direct = number(evidence && (evidence.anchorInstallment || evidence.installmentNumber || evidence.numeroCuota));
  if (direct != null && direct > 0) return Math.floor(direct);
  return installment(evidence && (evidence.installment || evidence.cuota || evidence.anchorInstallmentLabel)).index;
}
function sortedReceipts(receipts) {
  return [].concat(receipts || []).filter(activeReceipt).map(row => Object.assign({}, row, { __sequence: receiptSequence(row) }))
    .filter(row => row.__sequence != null).sort((a, b) => a.__sequence - b.__sequence || text(a.id).localeCompare(text(b.id)));
}
function resolveAnchor(receipts, evidence) {
  const receiptId = text(evidence && (evidence.receiptId || evidence.reciboId), 180);
  if (receiptId) {
    const exact = receipts.filter(row => text(row.id, 180) === receiptId);
    return { index: exact.length === 1 ? exact[0].__sequence : null, matches: exact };
  }
  const idx = anchorIndex(evidence);
  return { index: idx, matches: idx == null ? [] : receipts.filter(row => row.__sequence === idx) };
}
function planEvidence(input) {
  input = input || {};
  const policy = input.policy || {}, evidence = input.evidence || {}, config = input.reconciliationConfig || {};
  const type = evidenceKind(evidence.evidenceType || evidence.type || evidence.sourceType);
  if (!type) return review('EVIDENCE_TYPE_UNSUPPORTED');
  // Only the server-owned proposal command supplies this separate trusted
  // context. A browser evidence payload can never self-approve an inference.
  const manualApproval = input.humanApproval && input.humanApproval.authorized === true &&
    !!text(input.humanApproval.reference,500);
  if (manualApproval && config.manualApplicationEnabled === false) return review('PROPOSAL_MANUAL_APPLICATION_DISABLED');
  if (!manualApproval && config.autoCommitHighConfidence !== true) return review('TENANT_HIGH_CONFIDENCE_AUTO_COMMIT_NOT_ENABLED');
  if (!manualApproval && (config.humanConfirmationRequiredForHighConfidence === true || config.humanConfirmationRequired === true)) return review('TENANT_CONFIG_REQUIRES_HUMAN_CONFIRMATION');

  if ([].concat(input.receipts || []).filter(activeReceipt).some(row=>canonicalReceiptInstallment(row).conflict))
    return review('CANONICAL_INSTALLMENT_CONFLICT');
  const rows = sortedReceipts(input.receipts);
  if (!rows.length) return review('NO_ACTIVE_NUMBERED_RECEIPTS');
  const anchor = resolveAnchor(rows, evidence);
  if (anchor.matches.length !== 1) return review(anchor.matches.length > 1 ? 'AMBIGUOUS_ANCHOR_RECEIPT' : 'ANCHOR_RECEIPT_NOT_FOUND', { anchorInstallment: anchor.index });
  const anchorReceipt = anchor.matches[0], n = anchorReceipt.__sequence;
  if (!(n > 0)) return review('ANCHOR_INSTALLMENT_INVALID');

  const total = explicitTotal(evidence, anchorReceipt);
  const planRule = ruleForPolicy(config, policy);
  let installmentException = null;
  if (planRule && norm(planRule.scope || 'fraccionado') === 'fraccionado') {
    const max = Math.floor(number(planRule.maxInstallments) || 0);
    const exceptionalMax = Math.floor(number(planRule.exceptionalMaxInstallments || planRule.maxInstallmentsException) || 0);
    if (max > 0 && total && total > max) {
      const exceptionWithinCeiling = exceptionalMax > max && total <= exceptionalMax;
      const explicitException = evidence.explicitInstallmentException === true || evidence.installmentExceptionApproved === true;
      const exceptionReference = text(evidence.installmentExceptionReference || evidence.exceptionReference || evidence.planExceptionReference, 500);
      if (exceptionWithinCeiling) {
        if (!explicitException || !exceptionReference) {
          return review('INSTALLMENT_TOTAL_REQUIRES_EXPLICIT_EXCEPTION', {
            totalInstallments: total,
            maxInstallments: max,
            exceptionalMaxInstallments: exceptionalMax,
            insurerRule: text(planRule.insurer || planRule.name || planRule.canonicalKey)
          });
        }
        installmentException = {
          explicit: true,
          reference: exceptionReference,
          standardMaxInstallments: max,
          exceptionalMaxInstallments: exceptionalMax
        };
      } else {
        return review('INSTALLMENT_TOTAL_EXCEEDS_TENANT_CONFIG', {
          totalInstallments: total,
          maxInstallments: max,
          exceptionalMaxInstallments: exceptionalMax || null,
          insurerRule: text(planRule.insurer || planRule.name || planRule.canonicalKey)
        });
      }
    }
  }
  if (total && rows.length !== total) {
    return review('EXPECTED_RECEIPT_COUNT_MISMATCH', {
      expectedReceiptCount: total,
      actualReceiptCount: rows.length,
      scheduleCorrectionRequired: true,
      correctionMode: 'CONTROLLED_IDEMPOTENT_RECEIPT_PLAN_CORRECTION'
    });
  }
  const duplicates = new Set();
  for (const row of rows) {
    if (duplicates.has(row.__sequence)) return review('DUPLICATE_INSTALLMENT_SEQUENCE', { installment: row.__sequence });
    duplicates.add(row.__sequence);
  }

  const prior = rows.filter(row => row.__sequence < n);
  if (['INVOICE_INSTALLMENT_N','INSURER_STATEMENT_PENDING_FROM_N','COMMISSION_STATEMENT_INSTALLMENT_N'].includes(type)) {
    for (let i = 1; i < n; i += 1) if (!duplicates.has(i)) return review('NON_CONTIGUOUS_RECEIPT_SEQUENCE', { missingInstallment: i, anchorInstallment: n });
  }
  if (rows.some(contradiction)) return review('CONTRADICTORY_PAYMENT_STATE');

  const evidenceId = text(evidence.evidenceId || evidence.sourceRef || evidence.documentRef, 500);
  if (!evidenceId) return review('EVIDENCE_REFERENCE_REQUIRED');
  const evidenceAsOfDate = text(evidence.evidenceAsOfDate || evidence.fechaCorteEvidencia, 32);
  const ruleId = type === 'INVOICE_INSTALLMENT_N' ? 'INVOICE_CONTIGUOUS_PRIOR'
    : type === 'INSURER_STATEMENT_PENDING_FROM_N' ? 'INSURER_PENDING_FROM_CONTIGUOUS_PRIOR'
    : type === 'COMMISSION_STATEMENT_INSTALLMENT_N' ? 'COMMISSION_CONTIGUOUS_PRIOR'
    : 'BANK_EXACT_RECEIPT';

  const targets = [];
  const inferredPrior = prior.filter(row => !alreadyPaid(row));
  if (type !== 'BANK_STATEMENT_MATCH' || evidence.allowPriorContiguousInference === true) {
    if (type !== 'BANK_STATEMENT_MATCH' || evidence.allowPriorContiguousInference === true) {
      for (const row of inferredPrior) {
        const scheduledDate = dueDate(row);
        if (!scheduledDate) return review('INFERRED_INSTALLMENT_DUE_DATE_REQUIRED', { installment: row.__sequence });
        targets.push({
          receiptId: text(row.id, 180),
          installment: row.__sequence,
          mode: 'INFERRED',
          paymentState: 'PAID_INFERRED',
          applicationState: 'APPLIED_INFERRED',
          inferredEffectiveDate: scheduledDate,
          paidDate: '',
          directEvidence: false
        });
      }
    }
  }
  if (type !== 'INSURER_STATEMENT_PENDING_FROM_N') {
    targets.push({
      receiptId: text(anchorReceipt.id, 180),
      installment: n,
      mode: 'DIRECT',
      paymentState: 'PAID_DIRECT',
      applicationState: type === 'BANK_STATEMENT_MATCH' ? 'PENDING_APPLICATION' : 'APPLIED_DIRECT',
      inferredEffectiveDate: '',
      paidDate: text(evidence.paidDate || evidence.fechaPago, 32),
      directEvidence: true
    });
  }

  const currency = text(evidence.currency || evidence.moneda || policy.moneda, 12).toUpperCase();
  const policyCurrency = text(policy.moneda, 12).toUpperCase();
  if (config.requireSameCurrency !== false && currency && policyCurrency && currency !== policyCurrency) return review('CURRENCY_MISMATCH');
  if (evidence.uniqueMatch === false) return review('MATCH_NOT_UNIQUE');
  if (evidence.conflictingEvidence === true || evidence.partialPayment === true || evidence.reversal === true) return review('EVIDENCE_CONTRADICTION');

  // A bank match proves only the exact amount/currency allocated to its receipt.
  // A policy or installment match alone must never settle a different amount.
  // Commission statements may express the commission, not the premium; keep
  // their independent inference semantics unchanged.
  if (type === 'BANK_STATEMENT_MATCH') {
    const rawAmount = evidence.amount != null ? evidence.amount : evidence.monto;
    const bankAmount = rawAmount == null || rawAmount === '' ? NaN : Number(rawAmount);
    if (!Number.isFinite(bankAmount) || bankAmount <= 0) return review('BANK_AMOUNT_REQUIRED');
    const bankCents = Math.round(bankAmount * 100);
    if (Math.abs(bankAmount * 100 - bankCents) > 1e-6) return review('BANK_AMOUNT_PRECISION_INVALID');
    let expectedAmount = null;
    for (const key of ['monto', 'montoTotal', 'primaTotal', 'saldo']) {
      if (anchorReceipt[key] == null || anchorReceipt[key] === '') continue;
      const candidate = Number(anchorReceipt[key]);
      if (Number.isFinite(candidate) && candidate > 0) { expectedAmount = candidate; break; }
    }
    if (expectedAmount == null) return review('BANK_RECEIPT_AMOUNT_REQUIRED');
    if (Math.abs(expectedAmount * 100 - Math.round(expectedAmount * 100)) > 1e-6 ||
        bankCents !== Math.round(expectedAmount * 100)) return review('BANK_AMOUNT_RECEIPT_MISMATCH');
    const bankCurrency = text(evidence.currency || evidence.moneda, 12).toUpperCase();
    const receiptCurrency = text(anchorReceipt.moneda || anchorReceipt.currency || policy.moneda, 12).toUpperCase();
    if (!bankCurrency || !receiptCurrency) return review('BANK_CURRENCY_REQUIRED');
    if (bankCurrency !== receiptCurrency || (policyCurrency && receiptCurrency !== policyCurrency))
      return review('BANK_RECEIPT_CURRENCY_MISMATCH');
  }

  return {
    ok: true,
    status: targets.length ? (manualApproval ? 'MANUAL_AUTHORIZED' : 'AUTO_COMMIT') : 'NOOP_ALREADY_SATISFIED',
    autoCommit: true,
    approvalMode: manualApproval ? 'MANUAL_AUTHORIZED' : 'AUTO_HIGH_CONFIDENCE',
    confidence: 'HIGH',
    humanReviewRequired: false,
    writes: 0,
    evidenceType: type,
    evidenceId,
    sourceRef: text(evidence.sourceRef || evidence.documentRef || evidenceId, 500),
    evidenceAsOfDate,
    anchorReceiptId: text(anchorReceipt.id, 180),
    anchorInstallment: n,
    totalInstallments: total || rows.length,
    inferenceRuleId: ruleId,
    matchedPolicyId: text(policy.id || evidence.policyId || evidence.polizaId, 180),
    insurerRule: planRule ? {
      insurer: text(planRule.insurer || planRule.name || planRule.canonicalKey),
      maxInstallments: Math.floor(number(planRule.maxInstallments) || 0),
      exceptionalMaxInstallments: Math.floor(number(planRule.exceptionalMaxInstallments || planRule.maxInstallmentsException) || 0) || null,
      exceptionRequiresExplicitEvidence: planRule.exceptionRequiresExplicitEvidence === true || planRule.exceptionRequiresExplicitApproval === true,
      scope: text(planRule.scope || 'fraccionado')
    } : null,
    installmentException,
    targets
  };
}

module.exports = Object.freeze({
  VERSION,
  planEvidence,
  evidenceKind,
  installment,
  canonicalReceiptInstallment,
  receiptSequence,
  ruleForPolicy
});

'use strict';

// The existing reconciliation callable owns source admission. This helper has
// no SDK, credentials, transport, or payment writer. All hashes/IDs below are
// server-derived; financial application remains a separate approved command.
const crypto=require('node:crypto');
const {canonicalReceiptInstallment}=require('./payment-inference-engine');
const INPUT_SCHEMA='gi-cobros-source-intake-v2';
const POINTER_SCHEMA='gi-cobros-ledger-active-pointer-v2';
const MANIFEST_SCHEMA='gi-cobros-ledger-run-manifest-v2';
const CONTRACT_VERSION='I6.6-source-intake-v2';
const OWNER='cobros-reconciliation-domain/intake_source_run';
const MAX_ROWS=100,MAX_RETAINED_RUNS=512;
const SHA=/^[a-f0-9]{64}(?![\s\S])/;
const ID=/^[A-Za-z0-9][A-Za-z0-9._:-]{1,179}(?![\s\S])/;
const RUN=/^cobledger_v2_[a-f0-9]{28}(?![\s\S])/;
const QA_SOURCE=/^b3005qa_i66_intake_[a-z0-9_]{12,80}(?![\s\S])/;
const QA_RUN=/^cobledgerqa_[a-f0-9]{28}(?![\s\S])/;
const TYPES=new Set(['INSURER_STATEMENT_PENDING_FROM_N','COMMISSION_STATEMENT_INSTALLMENT_N','INVOICE_INSTALLMENT_N','BANK_STATEMENT_MATCH']);
const CLASSES=['pagosReportados','evidenciasCobro','propuestasConciliacion','conciliacionHolds'];
const stable=v=>v==null?v:Array.isArray(v)?v.map(stable):typeof v==='object'?Object.fromEntries(Object.keys(v).sort().map(k=>[k,stable(v[k])])):v;
const digest=v=>crypto.createHash('sha256').update(JSON.stringify(stable(v))).digest('hex');
function fail(code){const e=new Error(code);e.code=code;throw e;}
function exact(value,max,code,optional=false){
 if(optional&&(value==null||value===''))return '';
 if(typeof value!=='string'||!value||value.length>max||value!==value.trim()||/[\u0000-\u001f\u007f]/.test(value))fail(code);
 return value;
}
function identifier(value,code,optional=false){const s=exact(value,180,code,optional);if(s&&!ID.test(s))fail(code);return s;}
function plain(value,code){if(!value||typeof value!=='object'||Array.isArray(value))fail(code);return value;}
function fields(value,allowed,code){plain(value,code);if(Object.keys(value).some(k=>!allowed.includes(k)))fail(code);}
function iso(value,code,optional=false){
 const s=exact(value,10,code,optional);if(!s)return '';
 if(!/^\d{4}-\d{2}-\d{2}(?![\s\S])/.test(s)||Number.isNaN(Date.parse(s+'T00:00:00Z'))||new Date(s+'T00:00:00Z').toISOString().slice(0,10)!==s)fail(code);
 return s;
}
function bool(value,code){if(value!=null&&typeof value!=='boolean')fail(code);return value===true;}
function nullableAmount(value){
 if(value==null||value==='')return null;
 if(typeof value!=='number'||!Number.isFinite(value)||value<0||value>1000000000||Math.abs(value*100-Math.round(value*100))>1e-6)fail('SOURCE_AMOUNT_INVALID');
 return Math.round(value*100)/100;
}
function driveReference(value){
 const s=exact(value,500,'SOURCE_DOCUMENT_REFERENCE_REQUIRED');
 if(/^(?:(?:drive|gdrive):)?[A-Za-z0-9_-]{10,180}(?![\s\S])/.test(s))return s;
 if(/^https:\/\/drive\.google\.com\/file\/d\/[A-Za-z0-9_-]{10,180}\/view(?![\s\S])/.test(s)||
    /^https:\/\/drive\.google\.com\/open\?id=[A-Za-z0-9_-]{10,180}(?![\s\S])/.test(s))return s;
 fail('SOURCE_DOCUMENT_REFERENCE_INVALID');
}
function numberPair(row){
 const raw=row.installment==null?'':String(row.installment);
 const m=/^(\d{1,3})(?:\/(\d{1,3}))?(?![\s\S])/.exec(raw);
 if(raw&&!m)fail('SOURCE_INSTALLMENT_INVALID');
 const n=m?Number(m[1]):null;
 const t=row.totalInstallments==null||row.totalInstallments===''?(m&&m[2]?Number(m[2]):null):row.totalInstallments;
 if(t!=null&&(!Number.isInteger(t)||t<1||t>100))fail('SOURCE_INSTALLMENT_TOTAL_INVALID');
 if(m&&m[2]&&Number(m[2])!==t||n!=null&&(!Number.isInteger(n)||n<1||n>100||t&&n>t))fail('SOURCE_INSTALLMENT_INVALID');
 return {installment:n==null?'':String(n)+(t?'/'+t:''),installmentIndex:n,totalInstallments:t};
}
function canonicalPolicyDate(policy,edge){
 const names=edge==='start'?['vigenciaInicio','vigenciaDesde','inicioVigencia','fechaInicio']:['vigenciaFin','vigenciaHasta','finVigencia','fechaFin'];
 const values=names.map(key=>policy&&policy[key]).filter(value=>value!=null&&value!=='').map(value=>String(value).trim());
 return values.length&&new Set(values).size===1?values[0]:'';
}
function matchesCanonicalInstallment(sourceRow,policy,receipt){
 const declared=/^(\d+)(?:\/(\d+))?(?![\s\S])/.exec(String(sourceRow&&sourceRow.installment||''));
 if(!declared)return false;
 // Intake and application share the same quota interpretation. Legacy serie
 // may prove N/total; a numeric insurer requirement cannot supply either part.
 const canonical=canonicalReceiptInstallment(receipt),totals=canonical.total==null?[]:[canonical.total];
 if(canonical.conflict||canonical.index==null||canonical.index!==Number(declared[1]))return false;
 for(const value of [policy&&policy.cuotas]){
  if(value==null||value==='')continue;
  if(!/^\d{1,3}(?![\s\S])/.test(String(value)))return false;totals.push(Number(value));
 }
 if(totals.some(t=>t<1||t>100||t<canonical.index)||new Set(totals).size>1)return false;
 return !declared[2]||totals.length>0&&totals.every(total=>total===Number(declared[2]));
}
function prepareInput(tenantId,payload){
 fields(payload,['schemaVersion','source','sourceAttestation','rows'],'SOURCE_INTAKE_PAYLOAD_INVALID');
 if(payload.schemaVersion!==INPUT_SCHEMA||payload.sourceAttestation!==true)fail('SOURCE_ATTESTATION_REQUIRED');
 fields(payload.source,['sourceId','documentRef','fileName','sha256','evidenceAsOfDate','country','currency','evidenceType','insurerId','completePolicyGroups','extractionFile'],'SOURCE_METADATA_INVALID');
 const s=payload.source;
 const source={sourceId:identifier(s.sourceId,'SOURCE_ID_REQUIRED'),documentRef:driveReference(s.documentRef),
  fileName:exact(s.fileName,180,'SOURCE_FILE_NAME_REQUIRED'),sha256:exact(s.sha256,64,'SOURCE_SHA256_REQUIRED'),
  evidenceAsOfDate:iso(s.evidenceAsOfDate,'SOURCE_CUT_DATE_INVALID'),country:exact(s.country,2,'SOURCE_COUNTRY_REQUIRED'),
  currency:exact(s.currency,3,'SOURCE_CURRENCY_REQUIRED'),evidenceType:exact(s.evidenceType,80,'SOURCE_EVIDENCE_TYPE_REQUIRED'),
  insurerId:identifier(s.insurerId,'SOURCE_INSURER_ID_REQUIRED'),completePolicyGroups:bool(s.completePolicyGroups,'SOURCE_GROUP_ATTESTATION_INVALID')};
 if(s.extractionFile!=null){
